"""Form 5 Religious Studies practice: Old Testament I and II, and Synoptic Gospels I, one set per lesson."""

from .dsl import *  # noqa: F403

COURSE = ("religious-studies", "form-5")

OT1 = "Old Testament I: Creation to Exodus"
OT2 = "Old Testament II: Monarchy & Prophets"
GOS1 = "Synoptic Gospels I: Birth & Galilean Ministry"

_POSITIONS = [2, 0, 3, 1, 3, 0, 1, 2, 1, 3, 0, 2, 0, 2, 3, 1]
_COUNT = []


def Q(prompt, right, wrongs, expl, concept, skill, hint):
    """Four-option question. `right` is the correct option text; `wrongs` is three (text, why) pairs.
    The correct option is placed at a rotating position so answers spread over A-D."""
    target = _POSITIONS[len(_COUNT) % len(_POSITIONS)]
    _COUNT.append(1)
    others = [C(t, why=w) for t, w in wrongs]
    choices = others[:target] + [C(right, correct=True)] + others[target:]
    return MC(prompt, choices, steps=[S("Answer", text=expl)], concept=concept, skill=skill, hint=hint)


